<?php

namespace App\Models;

use App\Models\Concerns\BelongsToWorkspace;
use App\Models\Concerns\HasFriendlyId;
use Database\Factories\InvoiceFactory;
use Illuminate\Database\Eloquent\Attributes\Fillable;
use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\HasMany;
use Illuminate\Support\Carbon;

/**
 * An issued invoice, generated by a recurrence or sent once (US-6.7), in
 * the workspace of its recurrence (or the one picked for a one-off).
 * `number` is the `YYYYMM-NNN` of its workspace taken from
 * `invoice_number_sequences` and never reused. The payer and issuer fields are a snapshot: the PDF does
 * not change when their records are edited or deleted.
 *
 * @property int $id
 * @property int $workspace_id
 * @property string $friendly_id
 * @property int|null $invoice_recurrence_id
 * @property string|null $period_key
 * @property string $number
 * @property string $number_year_month
 * @property int $number_sequence
 * @property int $invoice_status_id
 * @property Carbon $issue_date
 * @property Carbon $due_date
 * @property int $currency_id
 * @property string $amount
 * @property string $service_description
 * @property string $email_subject
 * @property string $email_body
 * @property int|null $payer_id
 * @property string $payer_name
 * @property string $payer_address
 * @property int|null $issuer_id
 * @property string $issuer_name
 * @property string $issuer_email
 * @property string $issuer_postal_code
 * @property string $issuer_street
 * @property string $issuer_district
 * @property string $issuer_city
 * @property string $issuer_state
 * @property int|null $mail_service_id
 * @property int $locale_id
 * @property string|null $pdf_path
 * @property Carbon|null $sent_at
 * @property int|null $approved_by_id
 * @property int|null $created_by_id
 * @property Carbon|null $created_at
 * @property Carbon|null $updated_at
 * @property-read InvoiceRecurrence|null $recurrence
 * @property-read InvoiceStatus $status
 * @property-read Currency $currency
 * @property-read Payer|null $payer
 * @property-read Issuer|null $issuer
 * @property-read MailService|null $mailService
 * @property-read Locale $locale
 * @property-read User|null $approvedBy
 * @property-read User|null $createdBy
 */
#[Fillable([
    'workspace_id', 'invoice_recurrence_id', 'period_key', 'number', 'number_year_month', 'number_sequence', 'invoice_status_id',
    'issue_date', 'due_date', 'currency_id', 'amount', 'service_description', 'email_subject', 'email_body',
    'payer_id', 'payer_name', 'payer_address', 'issuer_id', 'issuer_name', 'issuer_email', 'issuer_postal_code',
    'issuer_street', 'issuer_district', 'issuer_city', 'issuer_state', 'mail_service_id', 'locale_id', 'pdf_path', 'sent_at', 'approved_by_id',
    'created_by_id',
])]
class Invoice extends Model
{
    /** @use HasFactory<InvoiceFactory> */
    use BelongsToWorkspace, HasFactory, HasFriendlyId;

    public static function idPrefix(): string
    {
        return 'invc';
    }

    public static function workspaceModule(): string
    {
        return Module::INVOICES;
    }

    /**
     * Get the attributes that should be cast.
     *
     * @return array<string, string>
     */
    protected function casts(): array
    {
        return [
            'number_sequence' => 'integer',
            'issue_date' => 'date',
            'due_date' => 'date',
            'amount' => 'decimal:2',
            'sent_at' => 'datetime',
        ];
    }

    public function isDraft(): bool
    {
        return $this->hasStatus(InvoiceStatus::DRAFT);
    }

    public function isFailed(): bool
    {
        return $this->hasStatus(InvoiceStatus::FAILED);
    }

    /**
     * Still before sending (`draft` or `pending_review`): the only invoices
     * whose content may be edited, approved or cancelled (US-6.6).
     */
    public function isAwaitingSend(): bool
    {
        return $this->isDraft() || $this->isPendingReview();
    }

    /**
     * Already e-mailed once or tried and failed: the invoices that can be
     * sent again (US-6.7).
     */
    public function isResendable(): bool
    {
        return $this->isSent() || $this->isFailed();
    }

    /**
     * A delivery is queued and not settled yet: the invoice is being sent.
     */
    public function hasPendingDelivery(): bool
    {
        return $this->deliveries()->where('delivery_status_id', DeliveryStatus::idFor(DeliveryStatus::PENDING))->exists();
    }

    /**
     * Its content may still change and it may be approved (US-6.6).
     */
    public function isEditable(): bool
    {
        return $this->isAwaitingSend() && ! $this->hasPendingDelivery();
    }

    public function isSent(): bool
    {
        return $this->hasStatus(InvoiceStatus::SENT);
    }

    public function isPendingReview(): bool
    {
        return $this->hasStatus(InvoiceStatus::PENDING_REVIEW);
    }

    public function isCancelled(): bool
    {
        return $this->hasStatus(InvoiceStatus::CANCELLED);
    }

    /**
     * Null for a one-off invoice.
     *
     * @return BelongsTo<InvoiceRecurrence, $this>
     */
    public function recurrence(): BelongsTo
    {
        return $this->belongsTo(InvoiceRecurrence::class, 'invoice_recurrence_id')->withTrashed();
    }

    /**
     * @return BelongsTo<InvoiceStatus, $this>
     */
    public function status(): BelongsTo
    {
        return $this->belongsTo(InvoiceStatus::class, 'invoice_status_id');
    }

    /**
     * @return BelongsTo<Currency, $this>
     */
    public function currency(): BelongsTo
    {
        return $this->belongsTo(Currency::class);
    }

    /**
     * The payer the snapshot came from, even if soft-deleted since.
     *
     * @return BelongsTo<Payer, $this>
     */
    public function payer(): BelongsTo
    {
        return $this->belongsTo(Payer::class)->withTrashed();
    }

    /**
     * The issuer the snapshot came from, even if soft-deleted since.
     *
     * @return BelongsTo<Issuer, $this>
     */
    public function issuer(): BelongsTo
    {
        return $this->belongsTo(Issuer::class)->withTrashed();
    }

    /**
     * The service it is e-mailed through, as picked when it was issued;
     * null for the default mailer.
     *
     * @return BelongsTo<MailService, $this>
     */
    public function mailService(): BelongsTo
    {
        return $this->belongsTo(MailService::class);
    }

    /**
     * The language its e-mail is written in, as picked when it was issued.
     *
     * @return BelongsTo<Locale, $this>
     */
    public function locale(): BelongsTo
    {
        return $this->belongsTo(Locale::class);
    }

    /**
     * @return HasMany<InvoiceRecipient, $this>
     */
    public function recipients(): HasMany
    {
        return $this->hasMany(InvoiceRecipient::class);
    }

    /**
     * @return HasMany<InvoiceDelivery, $this>
     */
    public function deliveries(): HasMany
    {
        return $this->hasMany(InvoiceDelivery::class);
    }

    /**
     * Who approved the invoice in review (US-6.6).
     *
     * @return BelongsTo<User, $this>
     */
    public function approvedBy(): BelongsTo
    {
        return $this->belongsTo(User::class, 'approved_by_id');
    }

    /**
     * Null when the scheduler generated the invoice.
     *
     * @return BelongsTo<User, $this>
     */
    public function createdBy(): BelongsTo
    {
        return $this->belongsTo(User::class, 'created_by_id');
    }

    private function hasStatus(string $slug): bool
    {
        return $this->invoice_status_id === InvoiceStatus::idFor($slug);
    }
}
